mapper.select:
select
    count(1) as answer_count,
    count(*) filter (where answer_status = 'REVIEWED') as reviewed_answer_count,
    avg(total_score) filter (where answer_status = 'REVIEWED') as average_total_score
from user_answers
where user_id = #{userId}
  and deleted = false
  and question_id is not null
  and created_at >= #{startAt}
  and created_at < #{endAt}

select
    count(1) as answer_count,
    count(*) filter (where answer_status = 'REVIEWED') as reviewed_answer_count,
    avg(total_score) filter (where answer_status = 'REVIEWED') as average_total_score
from user_answers
where user_id = #{userId}
  and deleted = false
  and question_id is null
  and created_at >= #{startAt}
  and created_at < #{endAt}

select count(1)
from user_answer_errors answer_error
inner join user_answers user_answer
    on user_answer.id = answer_error.user_answer_id
   and user_answer.user_id = #{userId}
   and user_answer.deleted = false
where answer_error.user_id = #{userId}
  and answer_error.created_at >= #{startAt}
  and answer_error.created_at < #{endAt}

select
    count(1) as review_attempt_count,
    count(*) filter (where result = 'PASS') as review_pass_count
from review_attempts
where user_id = #{userId}
  and attempt_source = 'REVIEW'
  and created_at >= #{startAt}
  and created_at < #{endAt}

select count(1)
from review_cycles review_cycle
inner join review_cards review_card
    on review_card.id = review_cycle.review_card_id
   and review_card.user_id = #{userId}
where review_cycle.status = 'COMPLETED'
  and review_cycle.completed_at >= #{startAt}
  and review_cycle.completed_at < #{endAt}
